function strip(rows,fractions,surface){const p=[],uv=[],ix=[],cols=fractions.length;for(const r of rows)for(const f of fractions){const a=surface(r,f);p.push(...a);uv.push(a[0]/2,a[2]/2);}for(let r=0;r<rows.length-1;r++)for(let j=0;j<cols-1;j++){const a=r*cols+j,b=a+1,c=a+cols,d=c+1;ix.push(a,b,c,b,d,c);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(ix);g.computeVertexNormals();return g;}
function pathMesh(k,m,path,offset=.0){const mesh=k.mesh(strip(path.rows,[-.5,.5],(r,f)=>[r.x+r.nx*r.width*f,r.y+offset,r.z+r.nz*r.width*f]),m,path.id);mesh.castShadow=false;mesh.userData={villageRoute:true,routeId:path.id,width:path.rows[0].width,length:path.length};if(path.id.startsWith('zugang-'))for(const side of [-1,1]){const rim=strip(path.rows,[0,1],(r,f)=>[r.x+r.nx*r.width*.5*side,r.y+offset-f*.38,r.z+r.nz*r.width*.5*side]);if(side<0)for(let i=0;i<rim.index.count;i+=3){const a=rim.index.getX(i);rim.index.setX(i,rim.index.getX(i+2));rim.index.setX(i+2,a);}rim.computeVertexNormals();const edge=k.mesh(rim,m,'Geschlossener Wegrand '+path.id);edge.userData={villagePavingEdge:true};}return mesh;}
function grading(k,m,path,height){const limits=new Map();for(const r of path.rows){const half=r.width/2+(ROADS.includes(path)?14:5),sides=[];for(const sign of [-1,1]){let edge=half;if(lakeContains(r.x+r.nx*sign*half,r.z+r.nz*sign*half)){let lo=0,hi=half;for(let i=0;i<14;i++){const a=(lo+hi)/2;if(lakeContains(r.x+r.nx*sign*a,r.z+r.nz*sign*a))hi=a;else lo=a;}edge=Math.max(r.width/2,lo-.20);}sides.push(edge);}limits.set(r,sides);}
 const mesh=k.mesh(strip(path.rows,Array.from({length:15},(_,i)=>(i-7)/7),(r,f)=>{const a=f*limits.get(r)[f<0?0:1],x=r.x+r.nx*a,z=r.z+r.nz*a;return [x,height(x,z)-.015,z];}),m.meadow,'Feine Geländeanbindung '+path.id);mesh.castShadow=false;mesh.userData={villageGrading:true,routeId:path.id};}
export function bench(k,m,x,y,z,angle=0,groundSurface=null){const g=new T.Group();g.name='Sitzbank Seealm';g.position.set(x,y,z);g.rotation.y=angle;g.userData={villageBench:true,footings:[]};k.root.add(g);const b=new Kit(g);for(let j=0;j<4;j++){b.box(m.wood,0,.46,-.20+j*.13,1.85,.06,.10);b.box(m.wood,0,.73+j*.11,-.28,1.85,.075,.06);}for(const side of [-1,1]){const wx=x+Math.cos(angle)*side*.65,wz=z-Math.sin(angle)*side*.65,bottom=(groundSurface?groundSurface(wx,wz):y+.025)-y,top=.455;g.userData.footings.push([side*.65,bottom,0]);b.box(m.frame,side*.65,(top+bottom)/2,0,.065,top-bottom,.40);b.box(m.frame,side*.65,.77,-.29,.06,.92,.055);}b.finish();return g;}
function shrub(k,m,x,y,z,random,scale=.65){for(let j=0;j<15;j++){const a=j*2.4,r=scale*(.14+random()*.5);k.put(broadLeaf,j%2?m.leaf:m.leaf2,x+Math.cos(a)*r,y+.08+random()*scale*.45,z+Math.sin(a)*r,scale*.40,scale*.73,scale*.44,-.5,a,.10);}}
export function tree(k,m,x,y,z,random,h=5.5){k.cyl(m.trunk,x,y+h*.36,z,.12,h*.72);for(let arm=0;arm<6;arm++){const a=arm*2.4,tip=[x+Math.cos(a)*h*.2,y+h*(.60+random()*.25),z+Math.sin(a)*h*.2];k.line(m.trunk,[x,y+h*.48,z],tip,.035);for(let j=0;j<24;j++){const q=j*2.4,r=h*(.06+random()*.12);k.put(broadLeaf,j%2?m.leaf:m.leaf2,tip[0]+Math.cos(q)*r,tip[1]+(random()-.5)*h*.20,tip[2]+Math.sin(q)*r,.40,.75,.50,-.6,q,.20);}}}
export function buildAlpineVillage(root,materials,height){const g=new T.Group();g.name='Seealm – Dorfplatz, Uferstraße und Promenade';g.userData={alpineVillage:true,version:43,dwellings:10,chapels:1,inns:1,townhalls:1};root.add(g);const m={...materials};for(const key of ['trunk','leaf','leaf2','grassBlade','warm']){m[key]=materials[key].clone();m[key].name='Dorf '+key;}m.leaf.color.set('#29442a');m.leaf2.color.set('#48603a');m.warm.emissiveIntensity=1.15;const contactMeshes=[],contactRay=new T.Raycaster(),entryHeight=(x,z)=>x>-211&&x<-168&&z>-142&&z<-102?renderedGroundHeight(x,z):height(x,z),surface=(x,z)=>{if(contactMeshes.length){contactRay.set(new T.Vector3(x,20,z),new T.Vector3(0,-1,0));const hit=contactRay.intersectObjects(contactMeshes,false)[0];if(hit)return hit.point.y;}return insideRegion(x,z,TRAFFIC.walk.polygons)?pavingHeight(x,z,height):height(x,z);},k=new Kit(g),random=rng(371003),built=BUILDINGS.map(b=>buildVillageBuilding(g,m,b,height));
 // Continuous terrain replaces overlapping grading ribbons.
 buildVillageTraffic(g,m,height);root.updateMatrixWorld(true);root.traverse(o=>{if(o.isMesh&&(o.userData.villageGround||['walk','loop','rest'].includes(o.userData.villageTrafficSurface)))contactMeshes.push(o);});
 for(const item of built){const {building:b,door,access}=item;let points;if(b.kind==='chapel')points=[[door.x,door.z,door.y],[-166,-150,item.floor],[-161,-145,4.45],[-155,-142,4.4]];else if(b.kind==='townhall')points=[[door.x,door.z,door.y],[-164.5,-156,4.31],[-164.5,-150,4.35]];else if(b.kind==='inn')points=[[door.x,door.z,door.y],[-145,-159,item.floor],[-148,-145,4.4],[-151,-138,4.4]];else if(b.kind==='shop')points=[[door.x,door.z,door.y],[-141,-154.9,4.45]];else points=[[door.x,door.z,door.y],[access.x,access.z,access.y+.025]];const path=route('zugang-'+b.id,points,1.65);const marker=new T.Object3D();marker.name='Hauszugang '+b.id;marker.userData={villageBuildingAccess:true,buildingId:b.id,points,boundaryTerminated:true};g.add(marker);
 if(!['chapel','inn','townhall','shop'].includes(b.kind)){for(const side of [-1,1]){const [x,z]=buildingPoint(b,side*(b.w/2+.8),0);shrub(k,m,x,entryHeight(x,z),z,random,.75);}const [x,z]=buildingPoint(b,0,-b.d/2-2.5),near=closestRoute(x,z);if(b.id!=='haus-7'&&!lakeContains(x,z)&&(!near||near.distance>near.width/2+3)){const gardenK=(x>=-156&&x<=-134&&z>=-165&&z<=-154)?new Kit(new T.Group()):k;gardenK.box(m.soil,x,entryHeight(x,z)+.03,z,3.7,.07,1.9,b.rot);for(let j=0;j<7;j++){const [px,pz]=buildingPoint(b,-1.5+j*.5,-b.d/2-2.5);shrub(gardenK,m,px,entryHeight(px,pz)+.05,pz,random,.42);}for(let j=-1;j<=1;j++){const [px,pz]=buildingPoint(b,j*1.85,-b.d/2-3.65);gardenK.box(m.wood,px,entryHeight(px,pz)+.38,pz,.06,.76,.06,b.rot);}for(const y of [.24,.57]){const [px,pz]=buildingPoint(b,0,-b.d/2-3.65);gardenK.box(m.wood,px,entryHeight(px,pz)+y,pz,3.8,.065,.065,b.rot);}}}}
 const forecourt=new T.Object3D();forecourt.name='Freier Vorbereich Gasthaus';forecourt.userData={villageInnForecourt:true,seating:0,facadeClear:true};g.add(forecourt);
 for(const rest of LAKE_RESTS){const r=rest.row,x=rest.x,z=rest.z,seat=bench(k,m,x,surface(x,z)-.025,z,Math.atan2(r.nx,r.nz),surface);Object.assign(seat.userData,{lakeside:true,padId:rest.id,loopFraction:rest.fraction,pathPoint:[r.x,r.z],waterDirection:[r.nx,r.nz]});}
 const er=MAIN_ROAD.rows.reduce((a,b)=>Math.hypot(a.x+181,a.z+99)<Math.hypot(b.x+181,b.z+99)?a:b),offset=er.width/2+3.45,ex=er.x+er.nx*offset,ez=er.z+er.nz*offset,ey=renderedGroundHeight(ex,ez),yaw=Math.atan2(-er.nz,er.nx);for(const dx of [-.68,.68]){const c=Math.cos(yaw),s=Math.sin(yaw);const bottom=renderedGroundHeight(ex+c*dx,ez-s*dx),top=ey+2;k.box(m.frame,ex+c*dx,(bottom+top)/2,ez-s*dx,.045,top-bottom,.045,yaw);}const sm=m.makeSign('Seealm',{subtitle:'AM BERGSEE',width:512,height:160,foreground:'#ede6d1',background:'#344239',italic:false});sm.name='Ortsschild Seealm';sm.emissive.set(0);sm.emissiveMap=null;sm.emissiveIntensity=1;const sign=k.mesh(new T.PlaneGeometry(1.75,.65),sm,'Dorfeinfahrt Seealm');sign.position.set(ex,ey+1.85,ez);sign.rotation.y=yaw;sign.userData={villageEntrance:true,relocated:true,roadStation:er.s,roadCenter:[er.x,er.z],roadWidth:er.width,vergeOffset:offset,groundY:ey,facingApproachingTraffic:true,oppositeRoadside:true,referenceStyleVersion:55};
 k.finish();return g;}
export function discardVillageTree(kit,build){const previous=new Map([...kit.batches].map(([key,b])=>[key,b.matrices.length]));build();let hit=false;for(const [key,b]of kit.batches){b.geom.computeBoundingBox();for(let i=previous.get(key)||0;i<b.matrices.length;i++){const box=b.geom.boundingBox.clone().applyMatrix4(b.matrices[i]),p=box.getCenter(new T.Vector3()),radius=Math.max(box.max.x-box.min.x,box.max.z-box.min.z)/2;if(p.x>=-58.5&&!closestRoute(p.x,p.z,[PROMENADE],radius))continue;const n=closestRoute(p.x,p.z,undefined,radius);if(Math.hypot(p.x-ROUNDABOUT.x,p.z-ROUNDABOUT.z)<ROUNDABOUT.outer+1.7+radius||inBuildingParcel(p.x,p.z,radius)||Math.abs(p.x-VILLAGE.square.x)<VILLAGE.square.width/2+radius&&Math.abs(p.z-VILLAGE.square.z)<VILLAGE.square.depth/2+radius||n&&n.distance<n.width/2+1.9+radius){hit=true;break;}}if(hit)break;}if(hit)for(const [key,b]of kit.batches){b.matrices.length=previous.get(key)||0;if(!b.matrices.length)kit.batches.delete(key);}return hit;}
export function clearVillageConstruction(scene,materials){const vegetation=new Set(['spruce','forestPine','trunk','pine','pine2','leaf','leaf2','grassBlade','shrub','flowerRed','flowerWhite'].map(k=>materials[k]));scene.updateMatrixWorld(true);scene.traverse(o=>{if(!o.isInstancedMesh||!vegetation.has(o.material))return;o.geometry.computeBoundingBox();const kept=[],matrix=new T.Matrix4();for(let i=0;i<o.count;i++){o.getMatrixAt(i,matrix);const b=o.geometry.boundingBox.clone().applyMatrix4(matrix.clone().premultiply(o.matrixWorld)),p=b.getCenter(new T.Vector3()),radius=Math.min(2,Math.max(b.max.x-b.min.x,b.max.z-b.min.z)/2),n=closestRoute(p.x,p.z,undefined,radius);const hit=(p.x<-58.5||n?.path===PROMENADE)&&(Math.hypot(p.x-ROUNDABOUT.x,p.z-ROUNDABOUT.z)<ROUNDABOUT.outer+1.7+radius||inBuildingParcel(p.x,p.z,radius)||Math.abs(p.x-VILLAGE.square.x)<VILLAGE.square.width/2+radius&&Math.abs(p.z-VILLAGE.square.z)<VILLAGE.square.depth/2+radius||n&&n.distance<n.width/2+.30+radius);if(!hit)kept.push(matrix.clone());}o.count=kept.length;kept.forEach((m,i)=>o.setMatrixAt(i,m));o.instanceMatrix.needsUpdate=true;o.computeBoundingBox();o.computeBoundingSphere();});}
